import {writeFile} from 'node:fs/promises';
import {lookup} from './unresolved.js';

export const normalizeNote = (text: string) => text.trim();

export async function saveNote(path: string, text: string, persist: boolean) {
  const normalized = normalizeNote(text);
  if (persist) {
    await writeFile(path, normalized);
  }
  return normalized;
}

export const saveCommand = (path: string, text: string) => saveNote(path, text, true);
export const previewCommand = (path: string, text: string) => saveNote(path, text, false);

export const queryNote = (text: string) => lookup(normalizeNote(text));

export function writeLookingPure(text: string) {
  const writeFile = (value: string) => value.trim();
  return writeFile(text);
}

import assert from 'node:assert/strict';
import {saveNote} from './operation.js';

export async function testSaveNote() {
  const result = await saveNote('fixture.txt', ' note ', false);
  assert.equal(result, 'note');
}

export function saveNoteNameOnly() {
  assert.ok('saveNote');
}
